"""Exercise real consumers against packages generated by the Python ABI writer."""
import importlib.util
import os
from pathlib import Path
import shlex
import subprocess

ROOT = Path(__file__).resolve().parents[1]
boot = (ROOT / 'main.c').read_text(encoding='utf-8').split('int main(void) {', 1)[1]
assert boot.index('services_init();') < boot.index('epd_resources_reload();') < boot.index('advertising_start();'), \
    'Boot must mount external resources after service/SPI init and before advertising/first refresh'
spec = importlib.util.spec_from_file_location('resource_pack', ROOT / 'tools/resource_pack.py')
pack = importlib.util.module_from_spec(spec)
spec.loader.exec_module(pack)
out = Path(os.environ.get('HOST_TEST_OUT', ROOT / '_build/host_tests'))
out.mkdir(parents=True, exist_ok=True)
layout = pack.load_layout()
payloads = {1: pack.table_payload(layout), 5: pack.calendar_payload(ROOT / 'tools/dist')[0],
            6: pack.ui_payload()[0], 7: pack.font_payload(ROOT / 'tools/dist')[0]}
flash = bytearray(b'\xff' * 524288)
for part in layout['partitions']:
    if part['id'] in payloads:
        image = pack.package(part['id'], payloads[part['id']], 1, 0)[:-12]
        offset = int(part['offset'], 0)
        flash[offset:offset + len(image)] = image
image = out / 'reload-flash.bin'
image.write_bytes(flash)
exe = out / 'test_resources_reload'
sources = ['EPD/resource_store.c', 'EPD/resource_crc.c', 'EPD/resource_crc_flash.c', 'EPD/font_store.c',
           'EPD/epd_resources.c', 'GUI/fonts.c', 'GUI/font_geometry.c', 'GUI/calendar_resources.c',
           'GUI/ui_resources.c', 'tests/test_resources_reload.c']
subprocess.run(shlex.split(os.environ.get('HOST_CC', 'gcc')) + [
    '-Wall', '-Werror', '-std=c11', '-I.', '-IEPD', '-IGUI',
    '-ISDK/17.1.0_ddde560/components/libraries/util',
    '-ISDK/17.1.0_ddde560/components/softdevice/s112/headers',
    '-DGUI_USE_EXTERNAL_FONTS=1', '-DGUI_INCLUDE_INTERNAL_FONTS=0',
    *sources, '-o', str(exe)], cwd=ROOT, check=True)
subprocess.run([str(exe.resolve()), str(image)], cwd=ROOT, check=True)
